# Try to solve 4-coloring using pysat
edges = [(0,5), (0,10), (0,24), (0,28), (1,5), (1,15), (1,16), (1,18), (1,19), (1,20), (1,25), (2,13), (2,15), (2,20), (2,22), (3,23), (3,30), (3,31), (4,12), (4,23), (4,29), (5,8), (5,12), (5,17), (5,19), (5,23), (5,30), (6,8), (6,13), (6,28), (6,29), (6,30), (6,31), (7,18), (7,23), (7,28), (7,31), (8,10), (8,31), (9,11), (9,12), (9,18), (9,22), (9,25), (10,12), (10,16), (10,26), (10,29), (11,14), (11,16), (11,17), (11,26), (12,13), (12,14), (12,17), (12,30), (14,17), (14,21), (14,25), (14,27), (15,24), (15,26), (15,28), (16,18), (16,20), (16,30), (17,23), (17,28), (17,29), (18,27), (18,29), (19,20), (21,23), (21,31), (22,28), (23,25), (23,30), (23,31), (24,25), (24,30), (24,31), (25,26), (27,28), (28,30), (30,31)]

n_vertices = 32
n_colors = 4

from pysat import SATSolver
s = SATSolver()

# variable index: vertex v, color c -> v*4 + c + 1 (1-indexed)
def var(v, c):
    return v * n_colors + c + 1

# Each vertex must have at least one color
for v in range(n_vertices):
    clause = [var(v, c) for c in range(n_colors)]
    s.add_clause(clause)

# No two adjacent vertices share a color
for u, v in edges:
    for c in range(n_colors):
        s.add_clause([-var(u, c), -var(v, c)])

# Optionally, at most one color per vertex (not strictly necessary but helps)
for v in range(n_vertices):
    for c1 in range(n_colors):
        for c2 in range(c1+1, n_colors):
            s.add_clause([-var(v, c1), -var(v, c2)])

result = s.solve()
print("Satisfiable:", result)
if result:
    model = s.get_model()
    # decode colors
    coloring = []
    for v in range(n_vertices):
        for c in range(n_colors):
            if var(v, c) in model:
                coloring.append(c)
                break
        else:
            coloring.append(-1)
    print("Coloring:", coloring)
    # Verify
    ok = True
    for u,v in edges:
        if coloring[u] == coloring[v]:
            print(f"Conflict: edge ({u},{v}) both color {coloring[u]}")
            ok = False
    print("Verification:", ok)
else:
    print("UNSAT")

